{
  "name": "SpikeGen: Pro Volleyball Team Maker",
  "description": "A specialized tool for indoor volleyball clubs to generate balanced teams using ELO ratings, gender distribution logic, and official setter priority rules.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Gender {
  MALE = 'MALE',
  FEMALE = 'FEMALE'
}

export interface Player {
  id: string;
  name: string;
  gender: Gender;
  isOfficialSetter: boolean;
  matchesPlayed: number;
  elo: number;
  arrivalOrder?: number;
}

export interface Team {
  setter: Player | null;
  players: Player[];
  totalElo: number;
}

export interface GenerationResult {
  teamA: Team;
  teamB: Team;
  remainingPlayers: Player[];
}

import { GoogleGenAI } from "@google/genai";
import { Team } from "../types";

export const analyzeMatch = async (teamA: Team, teamB: Team): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    As a volleyball expert, analyze this match-up:

    Team A (Total ELO: ${teamA.totalElo}):
    Setter: ${teamA.setter?.name || 'Temporary'}
    Players: ${teamA.players.map(p => `${p.name} (${p.elo})`).join(', ')}

    Team B (Total ELO: ${teamB.totalElo}):
    Setter: ${teamB.setter?.name || 'Temporary'}
    Players: ${teamB.players.map(p => `${p.name} (${p.elo})`).join(', ')}

    Briefly comment on the balance, potential key players, and which team might have a slight advantage. Keep it professional and concise.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Analysis unavailable.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Failed to analyze match.";
  }
};

import { Player, Gender, Team, GenerationResult } from '../types';

export function generateTeams(attendanceList: Player[]): GenerationResult {
  // 1. Separate Official Setters
  const officialSetters = attendanceList.filter(p => p.isOfficialSetter);
  const others = attendanceList.filter(p => !p.isOfficialSetter);

  // Selection of Setters: fewest matches played, then arrival order
  const sortedOfficialSetters = [...officialSetters].sort((a, b) => {
    if (a.matchesPlayed !== b.matchesPlayed) {
      return a.matchesPlayed - b.matchesPlayed;
    }
    return (a.arrivalOrder || 0) - (b.arrivalOrder || 0);
  });

  let setterA: Player | null = null;
  let setterB: Player | null = null;
  let pool = [...others];

  if (sortedOfficialSetters.length >= 2) {
    setterA = sortedOfficialSetters[0];
    setterB = sortedOfficialSetters[1];
    // Return extra official setters to the pool
    pool = [...pool, ...sortedOfficialSetters.slice(2)];
  } else if (sortedOfficialSetters.length === 1) {
    setterA = sortedOfficialSetters[0];
    // setterB stays null, will be temporary
  }

  // Arrival order is already implicit in the attendance list slice 
  // but we need to pick only 10 players (+ 2 setters = 12 total) 
  // OR 11 if only 1 setter was official.
  const requiredPlayers = 10;
  const matchPool = pool.slice(0, requiredPlayers);
  const remaining = pool.slice(requiredPlayers);

  const men = matchPool.filter(p => p.gender === Gender.MALE).sort((a, b) => b.elo - a.elo);
  const women = matchPool.filter(p => p.gender === Gender.FEMALE).sort((a, b) => b.elo - a.elo);

  let playersA: Player[] = [];
  let playersB: Player[] = [];

  // 2. Distribute Men
  // Highest-ranked man for A, second for B, third for A...
  men.forEach((man, index) => {
    if (index % 2 === 0) {
      playersA.push(man);
    } else {
      playersB.push(man);
    }
  });

  // 3. Distribute Women
  // Balanced by ELO sum
  women.forEach(woman => {
    const eloA = playersA.reduce((sum, p) => sum + p.elo, 0) + (setterA?.elo || 0);
    const eloB = playersB.reduce((sum, p) => sum + p.elo, 0) + (setterB?.elo || 0);

    if (eloA <= eloB) {
      playersA.push(woman);
    } else {
      playersB.push(woman);
    }
  });

  const calculateTotalElo = (setter: Player | null, players: Player[]) => {
    return players.reduce((sum, p) => sum + p.elo, 0) + (setter?.elo || 0);
  };

  return {
    teamA: { setter: setterA, players: playersA, totalElo: calculateTotalElo(setterA, playersA) },
    teamB: { setter: setterB, players: playersB, totalElo: calculateTotalElo(setterB, playersB) },
    remainingPlayers: remaining
  };
}

import React, { useState, useCallback, useMemo } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  CheckCircle2, 
  Plus, 
  ShieldAlert,
  Sparkles,
  RefreshCw,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [players, setPlayers] = useState<Player[]>(INITIAL_PLAYERS);
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("Need at least 10 players for a match!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">SpikeGen</h1>
          </div>
          <div className="flex items-center space-x-4 text-sm text-slate-500 font-medium">
            <Calendar className="w-4 h-4" />
            <span>Match Day: {new Date().toLocaleDateString()}</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Left Column: Attendance Management */}
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
              <h2 className="font-semibold flex items-center gap-2">
                <Users className="w-4 h-4 text-indigo-600" />
                Arrival List ({attendance.length})
              </h2>
            </div>
            <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto">
              {attendance.length === 0 ? (
                <div className="text-center py-8 text-slate-400 italic text-sm">
                  No one here yet. Start clicking players!
                </div>
              ) : (
                attendance.map((player) => (
                  <div key={player.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-xl group hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-100 transition-all">
                    <div className="flex items-center gap-3">
                      <span className="text-xs font-bold text-slate-300">#{player.arrivalOrder}</span>
                      <div>
                        <p className="text-sm font-semibold">{player.name}</p>
                        <p className="text-[10px] text-slate-400 flex items-center gap-1">
                          {player.isOfficialSetter && <span className="bg-amber-100 text-amber-700 px-1 rounded uppercase">Setter</span>}
                          {player.gender} • {player.elo} ELO
                        </p>
                      </div>
                    </div>
                    <button 
                      onClick={() => removeAttendance(player.id)}
                      className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <LogOut className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-200">
              <button 
                onClick={handleGenerate}
                disabled={attendance.length < 10}
                className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 transition-all flex items-center justify-center gap-2"
              >
                Generate Teams
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </section>

          <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-4 bg-slate-50 border-b border-slate-200">
              <h2 className="font-semibold text-sm uppercase tracking-wider text-slate-500">Registered Members</h2>
            </div>
            <div className="p-2 grid grid-cols-1 gap-1">
              {availablePlayers.map(player => (
                <button
                  key={player.id}
                  onClick={() => registerAttendance(player)}
                  className="flex items-center justify-between p-3 rounded-xl hover:bg-indigo-50 transition-colors text-left"
                >
                  <div>
                    <p className="text-sm font-medium">{player.name}</p>
                    <p className="text-xs text-slate-400">{player.gender} • ELO {player.elo}</p>
                  </div>
                  <Plus className="w-4 h-4 text-indigo-400" />
                </button>
              ))}
            </div>
          </section>
        </div>

        {/* Right Column: Teams & Analysis */}
        <div className="lg:col-span-8 space-y-6">
          {!generationResult ? (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-2xl border border-dashed border-slate-300 text-slate-400 space-y-4">
              <Calendar className="w-16 h-16 opacity-20" />
              <p className="text-lg">Waiting for match generation...</p>
              <p className="text-sm max-w-xs text-center">Add at least 10 players to the arrival list to generate the first match of the day.</p>
            </div>
          ) : (
            <div className="space-y-6">
              {/* Teams Display */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <TeamCard title="Team A" team={generationResult.teamA} color="indigo" />
                <TeamCard title="Team B" team={generationResult.teamB} color="rose" />
              </div>

              {/* Analysis Section */}
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-5 h-5 text-amber-400" />
                    <h3 className="font-bold">Gemini Match Analysis</h3>
                  </div>
                  {!analysis && (
                    <button 
                      onClick={handleAnalyze}
                      disabled={isAnalyzing}
                      className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg font-bold transition-colors flex items-center gap-2"
                    >
                      {isAnalyzing ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Request Insight'}
                    </button>
                  )}
                </div>
                <div className="p-6">
                  {isAnalyzing ? (
                    <div className="space-y-3">
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-3/4"></div>
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-full"></div>
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-5/6"></div>
                    </div>
                  ) : analysis ? (
                    <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{analysis}</p>
                  ) : (
                    <div className="text-center py-6 text-slate-400 text-sm">
                      Click "Request Insight" for AI-powered team analysis.
                    </div>
                  )}
                </div>
              </div>

              {/* Bench / Next Ups */}
              {generationResult.remainingPlayers.length > 0 && (
                <div className="bg-slate-100 rounded-2xl p-6 border border-slate-200">
                  <h3 className="font-bold text-slate-500 mb-4 flex items-center gap-2">
                    <ShieldAlert className="w-4 h-4" />
                    Upcoming Players (On the bench)
                  </h3>
                  <div className="flex flex-wrap gap-2">
                    {generationResult.remainingPlayers.map(p => (
                      <span key={p.id} className="bg-white px-3 py-1.5 rounded-full text-xs font-medium border border-slate-200 shadow-sm">
                        {p.name}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const TeamCard: React.FC<{ title: string; team: any; color: 'indigo' | 'rose' }> = ({ title, team, color }) => {
  const colorClass = color === 'indigo' ? 'bg-indigo-600' : 'bg-rose-600';
  const textClass = color === 'indigo' ? 'text-indigo-600' : 'text-rose-600';
  const bgClass = color === 'indigo' ? 'bg-indigo-50' : 'bg-rose-50';

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col h-full">
      <div className={`p-4 ${colorClass} text-white flex justify-between items-center`}>
        <h3 className="font-bold text-lg">{title}</h3>
        <div className="text-right">
          <p className="text-[10px] uppercase font-bold opacity-70">Total ELO</p>
          <p className="text-xl font-black">{team.totalElo}</p>
        </div>
      </div>

      <div className="p-4 space-y-4 flex-grow">
        {/* Setter Slot */}
        <div className={`p-4 rounded-xl border-2 border-dashed ${team.setter ? 'border-amber-200 bg-amber-50' : 'border-slate-100 bg-slate-50'}`}>
          <p className="text-[10px] font-black text-amber-600 uppercase mb-2 tracking-widest">Primary Setter</p>
          {team.setter ? (
            <div className="flex justify-between items-center">
              <span className="font-bold text-slate-900">{team.setter.name}</span>
              <span className="text-xs font-medium px-2 py-0.5 bg-amber-200 text-amber-800 rounded-full">Official</span>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-2 text-slate-400">
              <p className="text-xs italic font-medium">Needs Temp Setter</p>
            </div>
          )}
        </div>

        {/* Players List */}
        <div className="space-y-2">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Rotation Players</p>
          {team.players.map((p: Player) => (
            <div key={p.id} className="flex justify-between items-center p-2 rounded-lg bg-slate-50 border border-slate-100">
              <div className="flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${p.gender === Gender.MALE ? 'bg-blue-400' : 'bg-pink-400'}`}></span>
                <span className="text-sm font-semibold">{p.name}</span>
              </div>
              <span className="text-xs font-mono text-slate-500">{p.elo}</span>
            </div>
          ))}
        </div>
      </div>

      <div className={`p-3 ${bgClass} border-t border-slate-100 flex justify-center gap-4`}>
        <div className="flex items-center gap-1">
          <CheckCircle2 className={`w-3 h-3 ${textClass}`} />
          <span className="text-[10px] font-bold text-slate-500 uppercase">Balanced</span>
        </div>
        <div className="flex items-center gap-1">
          <Users className={`w-3 h-3 ${textClass}`} />
          <span className="text-[10px] font-bold text-slate-500 uppercase">Full Squad</span>
        </div>
      </div>
    </div>
  );
};

export default App;

{
  "name": "SpikeGen: Gerador de Times de Vôlei",
  "description": "Uma ferramenta especializada para clubes de vôlei de quadra para gerar times equilibrados usando o sistema ELO, distribuição por gênero e regras de prioridade para levantadores oficiais.",
  "requestFramePermissions": []
}

import { GoogleGenAI } from "@google/genai";
import { Team } from "../types";

export const analyzeMatch = async (teamA: Team, teamB: Team): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Como um especialista em vôlei, analise este confronto e responda em PORTUGUÊS DO BRASIL:

    Time A (ELO Total: ${teamA.totalElo}):
    Levantador: ${teamA.setter?.name || 'Temporário'}
    Jogadores: ${teamA.players.map(p => `${p.name} (${p.elo})`).join(', ')}

    Time B (ELO Total: ${teamB.totalElo}):
    Levantador: ${teamB.setter?.name || 'Temporário'}
    Jogadores: ${teamB.players.map(p => `${p.name} (${p.elo})`).join(', ')}

    Comente brevemente sobre o equilíbrio, possíveis jogadores-chave e qual time pode ter uma ligeira vantagem. Seja profissional, técnico e conciso.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Análise indisponível no momento.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Falha ao analisar a partida.";
  }
};

import React, { useState, useCallback, useMemo } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  CheckCircle2, 
  Plus, 
  ShieldAlert,
  Sparkles,
  RefreshCw,
  LogOut
} from 'lucide-react';

const App: React.FC = () => {
  const [players, setPlayers] = useState<Player[]>(INITIAL_PLAYERS);
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const translateGender = (gender: Gender) => {
    return gender === Gender.MALE ? 'Masculino' : 'Feminino';
  };

  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("É necessário pelo menos 10 jogadores para uma partida!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">SpikeGen</h1>
          </div>
          <div className="flex items-center space-x-4 text-sm text-slate-500 font-medium">
            <Calendar className="w-4 h-4" />
            <span>Dia do Jogo: {new Date().toLocaleDateString('pt-BR')}</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* Coluna Esquerda: Gestão de Presença */}
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
              <h2 className="font-semibold flex items-center gap-2">
                <Users className="w-4 h-4 text-indigo-600" />
                Lista de Chegada ({attendance.length})
              </h2>
            </div>
            <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto">
              {attendance.length === 0 ? (
                <div className="text-center py-8 text-slate-400 italic text-sm">
                  Ninguém chegou ainda. Clique nos jogadores abaixo!
                </div>
              ) : (
                attendance.map((player) => (
                  <div key={player.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-xl group hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-100 transition-all">
                    <div className="flex items-center gap-3">
                      <span className="text-xs font-bold text-slate-300">#{player.arrivalOrder}</span>
                      <div>
                        <p className="text-sm font-semibold">{player.name}</p>
                        <p className="text-[10px] text-slate-400 flex items-center gap-1">
                          {player.isOfficialSetter && <span className="bg-amber-100 text-amber-700 px-1 rounded uppercase">Levantador</span>}
                          {translateGender(player.gender)} • {player.elo} ELO
                        </p>
                      </div>
                    </div>
                    <button 
                      onClick={() => removeAttendance(player.id)}
                      className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <LogOut className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-200">
              <button 
                onClick={handleGenerate}
                disabled={attendance.length < 10}
                className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 transition-all flex items-center justify-center gap-2"
              >
                Gerar Times
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </section>

          <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-4 bg-slate-50 border-b border-slate-200">
              <h2 className="font-semibold text-sm uppercase tracking-wider text-slate-500">Membros Registrados</h2>
            </div>
            <div className="p-2 grid grid-cols-1 gap-1">
              {availablePlayers.map(player => (
                <button
                  key={player.id}
                  onClick={() => registerAttendance(player)}
                  className="flex items-center justify-between p-3 rounded-xl hover:bg-indigo-50 transition-colors text-left"
                >
                  <div>
                    <p className="text-sm font-medium">{player.name}</p>
                    <p className="text-xs text-slate-400">{translateGender(player.gender)} • ELO {player.elo}</p>
                  </div>
                  <Plus className="w-4 h-4 text-indigo-400" />
                </button>
              ))}
            </div>
          </section>
        </div>

        {/* Coluna Direita: Times & Análise */}
        <div className="lg:col-span-8 space-y-6">
          {!generationResult ? (
            <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-2xl border border-dashed border-slate-300 text-slate-400 space-y-4">
              <Calendar className="w-16 h-16 opacity-20" />
              <p className="text-lg text-center">Aguardando a geração dos times...</p>
              <p className="text-sm max-w-xs text-center px-4">Adicione pelo menos 10 jogadores à lista de chegada para montar a primeira partida do dia.</p>
            </div>
          ) : (
            <div className="space-y-6">
              {/* Exibição dos Times */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <TeamCard title="Time A" team={generationResult.teamA} color="indigo" />
                <TeamCard title="Time B" team={generationResult.teamB} color="rose" />
              </div>

              {/* Seção de Análise */}
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Sparkles className="w-5 h-5 text-amber-400" />
                    <h3 className="font-bold">Análise Tática (IA)</h3>
                  </div>
                  {!analysis && (
                    <button 
                      onClick={handleAnalyze}
                      disabled={isAnalyzing}
                      className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg font-bold transition-colors flex items-center gap-2"
                    >
                      {isAnalyzing ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Solicitar Insight'}
                    </button>
                  )}
                </div>
                <div className="p-6">
                  {isAnalyzing ? (
                    <div className="space-y-3">
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-3/4"></div>
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-full"></div>
                      <div className="h-4 bg-slate-100 rounded animate-pulse w-5/6"></div>
                    </div>
                  ) : analysis ? (
                    <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{analysis}</p>
                  ) : (
                    <div className="text-center py-6 text-slate-400 text-sm">
                      Clique em "Solicitar Insight" para uma análise técnica movida a IA.
                    </div>
                  )}
                </div>
              </div>

              {/* Reserva / Próximos da Lista */}
              {generationResult.remainingPlayers.length > 0 && (
                <div className="bg-slate-100 rounded-2xl p-6 border border-slate-200">
                  <h3 className="font-bold text-slate-500 mb-4 flex items-center gap-2 text-sm uppercase tracking-widest">
                    <ShieldAlert className="w-4 h-4" />
                    Próximos da Lista (Reserva)
                  </h3>
                  <div className="flex flex-wrap gap-2">
                    {generationResult.remainingPlayers.map(p => (
                      <span key={p.id} className="bg-white px-3 py-1.5 rounded-full text-xs font-medium border border-slate-200 shadow-sm">
                        {p.name} ({p.elo})
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const TeamCard: React.FC<{ title: string; team: any; color: 'indigo' | 'rose' }> = ({ title, team, color }) => {
