        <div className="text-right">
          <p className="text-[10px] uppercase font-bold opacity-70">ELO Total</p>
          <p className="text-xl font-black">{team.totalElo}</p>
        </div>
      </div>

      <div className="p-4 space-y-4 flex-grow">
        {/* Slot do Levantador */}
        <div className={`p-4 rounded-xl border-2 border-dashed ${team.setter ? 'border-amber-200 bg-amber-50' : 'border-slate-100 bg-slate-50'}`}>
          <p className="text-[10px] font-black text-amber-600 uppercase mb-2 tracking-widest">Levantador Principal</p>
          {team.setter ? (
            <div className="flex justify-between items-center">
              <span className="font-bold text-slate-900">{team.setter.name}</span>
              <span className="text-xs font-medium px-2 py-0.5 bg-amber-200 text-amber-800 rounded-full">Oficial</span>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-2 text-slate-400">
              <p className="text-xs italic font-medium">Definir Levantador Temporário</p>
            </div>
          )}
        </div>

        {/* Lista de Jogadores de Linha */}
        <div className="space-y-2">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jogadores de Linha</p>
          {team.players.map((p: Player) => (
            <div key={p.id} className="flex justify-between items-center p-2 rounded-lg bg-slate-50 border border-slate-100">
              <div className="flex items-center gap-2">
                <span className={`w-2 h-2 rounded-full ${p.gender === Gender.MALE ? 'bg-blue-400' : 'bg-pink-400'}`}></span>
                <span className="text-sm font-semibold">{p.name}</span>
              </div>
              <span className="text-xs font-mono text-slate-500">{p.elo}</span>
            </div>
          ))}
        </div>
      </div>

      <div className={`p-3 ${bgClass} border-t border-slate-100 flex justify-center gap-4`}>
        <div className="flex items-center gap-1">
          <CheckCircle2 className={`w-3 h-3 ${textClass}`} />
          <span className="text-[10px] font-bold text-slate-500 uppercase">Equilibrado</span>
        </div>
        <div className="flex items-center gap-1">
          <Users className={`w-3 h-3 ${textClass}`} />
          <span className="text-[10px] font-bold text-slate-500 uppercase">Time Completo</span>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  CheckCircle2, 
  Plus, 
  ShieldAlert,
  Sparkles,
  RefreshCw,
  LogOut,
  Settings,
  Edit2,
  Trash2,
  Save,
  X,
  UserPlus
} from 'lucide-react';

type ViewMode = 'match' | 'members';

const App: React.FC = () => {
  // Estado para persistência de sócios
  const [players, setPlayers] = useState<Player[]>(() => {
    const saved = localStorage.getItem('spikegen_players');
    return saved ? JSON.parse(saved) : INITIAL_PLAYERS;
  });

  const [viewMode, setViewMode] = useState<ViewMode>('match');
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Estados para o formulário de sócio
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);

  // Persistir sócios sempre que a lista mudar
  useEffect(() => {
    localStorage.setItem('spikegen_players', JSON.stringify(players));
  }, [players]);

  const translateGender = (gender: Gender) => {
    return gender === Gender.MALE ? 'Masculino' : 'Feminino';
  };

  // --- Lógica de Sócios ---
  const savePlayer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const playerData: Player = {
      id: editingPlayer?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      gender: formData.get('gender') as Gender,
      isOfficialSetter: formData.get('isOfficialSetter') === 'on',
      elo: parseInt(formData.get('elo') as string) || 1200,
      matchesPlayed: parseInt(formData.get('matchesPlayed') as string) || 0,
    };

    if (editingPlayer) {
      setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? playerData : p));
    } else {
      setPlayers(prev => [...prev, playerData]);
    }

    setIsFormOpen(false);
    setEditingPlayer(null);
  };

  const deletePlayer = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este sócio?')) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setAttendance(prev => prev.filter(p => p.id !== id));
    }
  };

  const openNewPlayerForm = () => {
    setEditingPlayer(null);
    setIsFormOpen(true);
  };

  const openEditPlayerForm = (player: Player) => {
    setEditingPlayer(player);
    setIsFormOpen(true);
  };

  // --- Lógica de Partida ---
  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("É necessário pelo menos 10 jogadores para uma partida!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">SpikeGen</h1>
          </div>

          <nav className="hidden md:flex items-center bg-slate-100 p-1 rounded-xl">
            <button 
              onClick={() => setViewMode('match')}
              className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'match' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Dia do Jogo
            </button>
            <button 
              onClick={() => setViewMode('members')}
              className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'members' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Gestão de Sócios
            </button>
          </nav>

          <div className="flex items-center space-x-4 text-sm text-slate-500 font-medium">
            <Calendar className="w-4 h-4" />
            <span className="hidden sm:inline">Hoje: {new Date().toLocaleDateString('pt-BR')}</span>
          </div>
        </div>

        {/* Mobile Navigation */}
        <div className="md:hidden border-t border-slate-100 p-2 flex justify-center gap-2">
           <button 
              onClick={() => setViewMode('match')}
              className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wider ${viewMode === 'match' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}
            >
              Partida
            </button>
            <button 
              onClick={() => setViewMode('members')}
              className={`flex-1 py-2 rounded-lg text-xs font-bold uppercase tracking-wider ${viewMode === 'members' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-400'}`}
            >
              Sócios
            </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 flex-grow w-full">
        {viewMode === 'match' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Coluna Esquerda: Gestão de Presença */}
            <div className="lg:col-span-4 space-y-6">
              <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                  <h2 className="font-semibold flex items-center gap-2">
                    <Users className="w-4 h-4 text-indigo-600" />
                    Lista de Chegada ({attendance.length})
                  </h2>
                </div>
                <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto">
                  {attendance.length === 0 ? (
                    <div className="text-center py-8 text-slate-400 italic text-sm">
                      Ninguém chegou ainda. Clique nos jogadores abaixo!
                    </div>
                  ) : (
                    attendance.map((player) => (
                      <div key={player.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-xl group hover:bg-white hover:shadow-sm border border-transparent hover:border-slate-100 transition-all">
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-slate-300">#{player.arrivalOrder}</span>
                          <div>
                            <p className="text-sm font-semibold">{player.name}</p>
                            <p className="text-[10px] text-slate-400 flex items-center gap-1">
                              {player.isOfficialSetter && <span className="bg-amber-100 text-amber-700 px-1 rounded uppercase font-bold">Levantador</span>}
                              {translateGender(player.gender)} • {player.elo} ELO
                            </p>
                          </div>
                        </div>
                        <button 
                          onClick={() => removeAttendance(player.id)}
                          className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <LogOut className="w-4 h-4" />
                        </button>
                      </div>
                    ))
                  )}
                </div>
                <div className="p-4 bg-slate-50 border-t border-slate-200">
                  <button 
                    onClick={handleGenerate}
                    disabled={attendance.length < 10}
                    className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 transition-all flex items-center justify-center gap-2"
                  >
                    Gerar Times
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              </section>

              <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                  <h2 className="font-semibold text-sm uppercase tracking-wider text-slate-500">Sócios Disponíveis</h2>
                  <button onClick={() => setViewMode('members')} className="text-xs text-indigo-600 font-bold hover:underline">Ver Todos</button>
                </div>
                <div className="p-2 grid grid-cols-1 gap-1 max-h-[300px] overflow-y-auto">
                  {availablePlayers.length === 0 ? (
                    <div className="p-4 text-center text-slate-400 text-xs italic">Todos os sócios estão na lista ou não há cadastros.</div>
                  ) : (
                    availablePlayers.map(player => (
                      <button
                        key={player.id}
                        onClick={() => registerAttendance(player)}
                        className="flex items-center justify-between p-3 rounded-xl hover:bg-indigo-50 transition-colors text-left group"
                      >
                        <div>
                          <p className="text-sm font-medium">{player.name}</p>
                          <p className="text-xs text-slate-400">{translateGender(player.gender)} • ELO {player.elo}</p>
                        </div>
                        <Plus className="w-4 h-4 text-indigo-400 group-hover:text-indigo-600" />
                      </button>
                    ))
                  )}
                </div>
              </section>
            </div>

            {/* Coluna Direita: Times & Análise */}
            <div className="lg:col-span-8 space-y-6">
              {!generationResult ? (
                <div className="h-full min-h-[500px] flex flex-col items-center justify-center bg-white rounded-2xl border border-dashed border-slate-300 text-slate-400 space-y-4">
                  <Calendar className="w-16 h-16 opacity-20" />
                  <p className="text-lg text-center">Aguardando a geração dos times...</p>
                  <p className="text-sm max-w-xs text-center px-4">Adicione pelo menos 10 jogadores à lista de chegada para montar a primeira partida do dia.</p>
                </div>
              ) : (
                <div className="space-y-6">
                  {/* Exibição dos Times */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <TeamCard title="Time A" team={generationResult.teamA} color="indigo" />
                    <TeamCard title="Time B" team={generationResult.teamB} color="rose" />
                  </div>

                  {/* Seção de Análise */}
                  <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Sparkles className="w-5 h-5 text-amber-400" />
                        <h3 className="font-bold">Análise Tática (IA)</h3>
                      </div>
                      {!analysis && (
                        <button 
                          onClick={handleAnalyze}
                          disabled={isAnalyzing}
                          className="text-xs bg-white/10 hover:bg-white/20 px-3 py-1 rounded-lg font-bold transition-colors flex items-center gap-2"
                        >
                          {isAnalyzing ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Solicitar Insight'}
                        </button>
                      )}
                    </div>
                    <div className="p-6">
                      {isAnalyzing ? (
                        <div className="space-y-3">
                          <div className="h-4 bg-slate-100 rounded animate-pulse w-3/4"></div>
                          <div className="h-4 bg-slate-100 rounded animate-pulse w-full"></div>
                          <div className="h-4 bg-slate-100 rounded animate-pulse w-5/6"></div>
                        </div>
                      ) : analysis ? (
                        <p className="text-slate-600 leading-relaxed whitespace-pre-wrap">{analysis}</p>
                      ) : (
                        <div className="text-center py-6 text-slate-400 text-sm">
                          Clique em "Solicitar Insight" para uma análise técnica movida a IA.
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Reserva */}
                  {generationResult.remainingPlayers.length > 0 && (
                    <div className="bg-slate-100 rounded-2xl p-6 border border-slate-200">
                      <h3 className="font-bold text-slate-500 mb-4 flex items-center gap-2 text-sm uppercase tracking-widest">
                        <ShieldAlert className="w-4 h-4" />
                        Próximos da Lista (Reserva)
                      </h3>
                      <div className="flex flex-wrap gap-2">
                        {generationResult.remainingPlayers.map(p => (
                          <span key={p.id} className="bg-white px-3 py-1.5 rounded-full text-xs font-medium border border-slate-200 shadow-sm">
                            {p.name} ({p.elo})
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ) : (
          /* ABA DE GESTÃO DE SÓCIOS */
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Gestão de Sócios</h2>
                <p className="text-slate-500 text-sm">Cadastre, edite ou remova membros do clube.</p>
              </div>
              <button 
                onClick={openNewPlayerForm}
                className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
              >
                <UserPlus className="w-5 h-5" />
                Novo Sócio
              </button>
            </div>

            {/* Listagem de Sócios */}
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[600px]">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Gênero</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Levantador</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">ELO</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Partidas</th>
                    <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {players.sort((a,b) => a.name.localeCompare(b.name)).map(player => (
                    <tr key={player.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-4 font-semibold text-slate-900">{player.name}</td>
                      <td className="px-6 py-4 text-sm text-slate-500">{translateGender(player.gender)}</td>
                      <td className="px-6 py-4 text-center">
                        {player.isOfficialSetter ? (
                          <span className="inline-block bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase">Sim</span>
                        ) : (
                          <span className="inline-block bg-slate-100 text-slate-400 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase">Não</span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-center font-mono text-sm">{player.elo}</td>
                      <td className="px-6 py-4 text-center text-sm text-slate-500">{player.matchesPlayed}</td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => openEditPlayerForm(player)}
                            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                            title="Editar"
                          >
                            <Edit2 className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => deletePlayer(player.id)}
                            className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                            title="Excluir"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {players.length === 0 && (
                <div className="py-20 text-center text-slate-400">
                  <Users className="w-12 h-12 mx-auto mb-4 opacity-20" />
                  <p>Nenhum sócio cadastrado.</p>
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* MODAL DE FORMULÁRIO (ADD/EDIT) */}
      {isFormOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <h3 className="text-xl font-bold text-slate-900">
                {editingPlayer ? 'Editar Sócio' : 'Novo Sócio'}
              </h3>
              <button onClick={() => setIsFormOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-500" />
              </button>
            </div>

            <form onSubmit={savePlayer} className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Nome Completo</label>
                <input 
                  name="name" 
                  required 
                  defaultValue={editingPlayer?.name}
