export default App;

export enum Gender {
  MALE = 'MALE',
  FEMALE = 'FEMALE'
}

export interface Player {
  id: string;
  name: string;
  gender: Gender;
  isOfficialSetter: boolean;
  matchesPlayed: number;
  wins: number;
  losses: number;
  elo: number;
  arrivalOrder?: number;
}

export interface Team {
  setter: Player | null;
  players: Player[];
  totalElo: number;
}

export interface GenerationResult {
  teamA: Team;
  teamB: Team;
  remainingPlayers: Player[];
}

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult, Team } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  CheckCircle2, 
  Plus, 
  ShieldAlert,
  Sparkles,
  RefreshCw,
  LogOut,
  Edit2,
  Trash2,
  Save,
  X,
  UserPlus,
  BarChart3,
  TrendingUp,
  History,
  ArrowLeftRight,
  Medal,
  Check
} from 'lucide-react';

type ViewMode = 'match' | 'members' | 'dashboard';

const App: React.FC = () => {
  // --- Estados Principais ---
  const [players, setPlayers] = useState<Player[]>(() => {
    const saved = localStorage.getItem('spikegen_players_v2');
    return saved ? JSON.parse(saved) : INITIAL_PLAYERS;
  });

  const [viewMode, setViewMode] = useState<ViewMode>('match');
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // --- Estados de Gestão ---
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [swapSelection, setSwapSelection] = useState<{ team: 'A' | 'B'; playerId: string } | null>(null);

  // --- Persistência ---
  useEffect(() => {
    localStorage.setItem('spikegen_players_v2', JSON.stringify(players));
  }, [players]);

  const translateGender = (gender: Gender) => gender === Gender.MALE ? 'Masculino' : 'Feminino';

  // --- Lógica de Sócios ---
  const savePlayer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const playerData: Player = {
      id: editingPlayer?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      gender: formData.get('gender') as Gender,
      isOfficialSetter: formData.get('isOfficialSetter') === 'on',
      elo: parseInt(formData.get('elo') as string) || 1200,
      matchesPlayed: parseInt(formData.get('matchesPlayed') as string) || 0,
      wins: editingPlayer?.wins || 0,
      losses: editingPlayer?.losses || 0,
    };

    if (editingPlayer) {
      setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? playerData : p));
    } else {
      setPlayers(prev => [...prev, playerData]);
    }

    setIsFormOpen(false);
    setEditingPlayer(null);
  };

  const deletePlayer = (id: string) => {
    if (window.confirm('Deseja excluir este sócio?')) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setAttendance(prev => prev.filter(p => p.id !== id));
    }
  };

  // --- Lógica de Troca de Jogadores ---
  const handleSwapClick = (team: 'A' | 'B', playerId: string) => {
    if (!swapSelection) {
      setSwapSelection({ team, playerId });
    } else {
      if (swapSelection.team === team) {
        setSwapSelection({ team, playerId }); // Muda seleção no mesmo time
      } else {
        // Executa a troca entre times
        performSwap(swapSelection.playerId, playerId);
        setSwapSelection(null);
      }
    }
  };

  const performSwap = (id1: string, id2: string) => {
    if (!generationResult) return;

    const findAndReplace = (team: Team, oldId: string, newPlayer: Player) => {
      if (team.setter?.id === oldId) {
        return { ...team, setter: newPlayer };
      }
      return {
        ...team,
        players: team.players.map(p => p.id === oldId ? newPlayer : p)
      };
    };

    const p1 = [...players, ...attendance].find(p => p.id === id1)!;
    const p2 = [...players, ...attendance].find(p => p.id === id2)!;

    const newTeamA = findAndReplace(generationResult.teamA, id1, p2);
    const newTeamB = findAndReplace(generationResult.teamB, id2, p1);

    const calcElo = (t: Team) => (t.players.reduce((s, p) => s + p.elo, 0) + (t.setter?.elo || 0));

    setGenerationResult({
      ...generationResult,
      teamA: { ...newTeamA, totalElo: calcElo(newTeamA) },
      teamB: { ...newTeamB, totalElo: calcElo(newTeamB) }
    });
  };

  // --- Lógica de Encerramento de Partida ---
  const handleMatchWinner = (winner: 'A' | 'B') => {
    if (!generationResult) return;

    const winningPlayers = winner === 'A' ? 
      [generationResult.teamA.setter, ...generationResult.teamA.players].filter(Boolean) as Player[] :
      [generationResult.teamB.setter, ...generationResult.teamB.players].filter(Boolean) as Player[];

    const losingPlayers = winner === 'A' ? 
      [generationResult.teamB.setter, ...generationResult.teamB.players].filter(Boolean) as Player[] :
      [generationResult.teamA.setter, ...generationResult.teamA.players].filter(Boolean) as Player[];

    setPlayers(prev => prev.map(p => {
      const isWinner = winningPlayers.some(wp => wp.id === p.id);
      const isLoser = losingPlayers.some(lp => lp.id === p.id);

      if (isWinner) {
        return { ...p, elo: p.elo + 25, wins: p.wins + 1, matchesPlayed: p.matchesPlayed + 1 };
      }
      if (isLoser) {
        return { ...p, elo: Math.max(0, p.elo - 20), losses: p.losses + 1, matchesPlayed: p.matchesPlayed + 1 };
      }
      return p;
    }));

    alert(`Partida registrada! Vitória do Time ${winner}.`);
    setGenerationResult(null);
    setAttendance([]);
    setAnalysis('');
  };

  // --- Lógica de Partida ---
  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("É necessário pelo menos 10 jogadores para uma partida!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  // --- Renderização do Dashboard ---
  const renderDashboard = () => {
    const sortedRanking = [...players].sort((a, b) => b.elo - a.elo);
    const totalMatches = players.reduce((acc, p) => acc + p.matchesPlayed, 0) / 12; // Aprox
    const avgElo = players.length ? Math.round(players.reduce((acc, p) => acc + p.elo, 0) / players.length) : 0;

    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4 mb-2">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><TrendingUp className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">ELO Médio</p><p className="text-2xl font-black">{avgElo}</p></div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4 mb-2">
              <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><History className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">Total de Sócios</p><p className="text-2xl font-black">{players.length}</p></div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4 mb-2">
              <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><Trophy className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">Líder do Ranking</p><p className="text-2xl font-black truncate max-w-[150px]">{sortedRanking[0]?.name || '-'}</p></div>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex items-center gap-2">
            <Medal className="text-amber-500 w-5 h-5"/>
            <h3 className="font-bold text-lg">Top 10 Jogadores</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                <tr>
                  <th className="px-6 py-4">Posição</th>
                  <th className="px-6 py-4">Nome</th>
                  <th className="px-6 py-4 text-center">Partidas</th>
                  <th className="px-6 py-4 text-center">Vitórias</th>
                  <th className="px-6 py-4 text-center">Win Rate</th>
                  <th className="px-6 py-4 text-right">Pontuação ELO</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {sortedRanking.slice(0, 10).map((p, idx) => {
                  const winRate = p.matchesPlayed > 0 ? Math.round((p.wins / p.matchesPlayed) * 100) : 0;
                  return (
                    <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4">
                        <span className={`w-8 h-8 flex items-center justify-center rounded-lg font-bold ${idx === 0 ? 'bg-amber-100 text-amber-700' : idx === 1 ? 'bg-slate-200 text-slate-700' : idx === 2 ? 'bg-orange-100 text-orange-700' : 'text-slate-400'}`}>
                          {idx + 1}
                        </span>
                      </td>
                      <td className="px-6 py-4 font-bold text-slate-900">{p.name}</td>
                      <td className="px-6 py-4 text-center text-slate-500">{p.matchesPlayed}</td>
                      <td className="px-6 py-4 text-center text-indigo-600 font-semibold">{p.wins}</td>
                      <td className="px-6 py-4 text-center">
                        <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden max-w-[80px] mx-auto">
                          <div className="bg-indigo-500 h-full" style={{ width: `${winRate}%` }}></div>
                        </div>
                        <span className="text-[10px] font-bold text-slate-400">{winRate}%</span>
                      </td>
                      <td className="px-6 py-4 text-right font-mono font-bold text-indigo-600">{p.elo}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">SpikeGen</h1>
          </div>

          <nav className="hidden md:flex items-center bg-slate-100 p-1 rounded-xl">
            <button 
              onClick={() => setViewMode('match')}
              className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'match' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Dia do Jogo
            </button>
            <button 
              onClick={() => setViewMode('members')}
              className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'members' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Gestão de Sócios
            </button>
            <button 
              onClick={() => setViewMode('dashboard')}
              className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Dashboard
            </button>
          </nav>

          <div className="flex items-center space-x-4 text-sm text-slate-500 font-medium">
            <Calendar className="w-4 h-4" />
            <span className="hidden sm:inline">{new Date().toLocaleDateString('pt-BR')}</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 flex-grow w-full">
        {viewMode === 'match' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-4 space-y-6">
              <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                  <h2 className="font-semibold flex items-center gap-2"><Users className="w-4 h-4 text-indigo-600" />Lista de Chegada ({attendance.length})</h2>
                </div>
                <div className="p-4 space-y-2 max-h-[400px] overflow-y-auto">
                  {attendance.length === 0 ? (
                    <div className="text-center py-8 text-slate-400 italic text-sm">Ninguém chegou ainda.</div>
                  ) : (
                    attendance.map((player) => (
                      <div key={player.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-xl group hover:bg-white border border-transparent hover:border-slate-100 transition-all">
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-slate-300">#{player.arrivalOrder}</span>
                          <div>
                            <p className="text-sm font-semibold">{player.name}</p>
                            <p className="text-[10px] text-slate-400">{translateGender(player.gender)} • {player.elo} ELO</p>
                          </div>
                        </div>
                        <button onClick={() => removeAttendance(player.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><LogOut className="w-4 h-4" /></button>
                      </div>
                    ))
                  )}
                </div>
                <div className="p-4 bg-slate-50 border-t border-slate-200">
                  <button onClick={handleGenerate} disabled={attendance.length < 10} className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 text-white font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center gap-2">Gerar Times <ArrowRight className="w-4 h-4" /></button>
