export default App;

export enum Gender {
  MALE = 'MALE',
  FEMALE = 'FEMALE'
}

export interface Player {
  id: string;
  name: string;
  gender: Gender;
  isOfficialSetter: boolean;
  matchesPlayed: number; // Total histórico
  dailyMatches: number; // Partidas no dia atual
  wins: number;
  losses: number;
  elo: number;
  arrivalOrder?: number;
}

export interface Team {
  setter: Player | null;
  players: Player[];
  totalElo: number;
}

export interface GenerationResult {
  teamA: Team;
  teamB: Team;
  remainingPlayers: Player[];
}

import { Player, Gender, Team, GenerationResult } from '../types';

export function generateTeams(attendanceList: Player[]): GenerationResult {
  // 1. Separar Levantadores Oficiais
  const officialSetters = attendanceList.filter(p => p.isOfficialSetter);
  const others = attendanceList.filter(p => !p.isOfficialSetter);

  // Seleção de Levantadores: Menos partidas NO DIA, depois ordem de chegada
  const sortedOfficialSetters = [...officialSetters].sort((a, b) => {
    if (a.dailyMatches !== b.dailyMatches) {
      return a.dailyMatches - b.dailyMatches;
    }
    return (a.arrivalOrder || 0) - (b.arrivalOrder || 0);
  });

  let setterA: Player | null = null;
  let setterB: Player | null = null;
  let pool = [...others];

  if (sortedOfficialSetters.length >= 2) {
    setterA = sortedOfficialSetters[0];
    setterB = sortedOfficialSetters[1];
    // Devolve os outros levantadores para a lista comum para serem distribuídos como jogadores de linha
    pool = [...pool, ...sortedOfficialSetters.slice(2)];
  } else if (sortedOfficialSetters.length === 1) {
    setterA = sortedOfficialSetters[0];
  }

  // Define quantos jogadores de linha precisamos (6 por time, total 12 jogadores)
  // Se temos 2 levantadores, precisamos de 10 jogadores de linha.
  // Se temos 1, precisamos de 11 (um time terá levantador temporário).
  // Se temos 0, precisamos de 12 (ambos times com temporários).
  const settersCount = (setterA ? 1 : 0) + (setterB ? 1 : 0);
  const requiredLinePlayers = 12 - settersCount;

  const matchPool = pool.slice(0, requiredLinePlayers);
  const remaining = pool.slice(requiredLinePlayers);

  const men = matchPool.filter(p => p.gender === Gender.MALE).sort((a, b) => b.elo - a.elo);
  const women = matchPool.filter(p => p.gender === Gender.FEMALE).sort((a, b) => b.elo - a.elo);

  let playersA: Player[] = [];
  let playersB: Player[] = [];

  // 2. Distribuir Homens (Regra: 1º A, 2º B, 3º A...)
  men.forEach((man, index) => {
    if (index % 2 === 0) {
      playersA.push(man);
    } else {
      playersB.push(man);
    }
  });

  // 3. Distribuir Mulheres (Regra: Equilíbrio de ELO)
  women.forEach(woman => {
    const eloA = playersA.reduce((sum, p) => sum + p.elo, 0) + (setterA?.elo || 0);
    const eloB = playersB.reduce((sum, p) => sum + p.elo, 0) + (setterB?.elo || 0);

    // Tenta equilibrar somando onde o ELO está menor
    if (playersA.length < 6 && (eloA <= eloB || playersB.length >= 6)) {
      playersA.push(woman);
    } else {
      playersB.push(woman);
    }
  });

  const calculateTotalElo = (setter: Player | null, players: Player[]) => {
    return players.reduce((sum, p) => sum + p.elo, 0) + (setter?.elo || 0);
  };

  return {
    teamA: { setter: setterA, players: playersA, totalElo: calculateTotalElo(setterA, playersA) },
    teamB: { setter: setterB, players: playersB, totalElo: calculateTotalElo(setterB, playersB) },
    remainingPlayers: remaining
  };
}

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult, Team } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  CheckCircle2, 
  Plus, 
  ShieldAlert,
  Sparkles,
  RefreshCw,
  LogOut,
  Edit2,
  Trash2,
  Save,
  X,
  UserPlus,
  BarChart3,
  TrendingUp,
  History,
  ArrowLeftRight,
  Medal,
  Check,
  RotateCcw
} from 'lucide-react';

type ViewMode = 'match' | 'members' | 'dashboard';

const App: React.FC = () => {
  // --- Estados Principais ---
  const [players, setPlayers] = useState<Player[]>(() => {
    const saved = localStorage.getItem('spikegen_players_v3');
    if (saved) return JSON.parse(saved);
    return INITIAL_PLAYERS.map(p => ({ ...p, dailyMatches: 0 }));
  });

  const [viewMode, setViewMode] = useState<ViewMode>('match');
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // --- Estados de Gestão ---
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [swapSelection, setSwapSelection] = useState<{ team: 'A' | 'B'; playerId: string } | null>(null);

  // --- Persistência ---
  useEffect(() => {
    localStorage.setItem('spikegen_players_v3', JSON.stringify(players));
  }, [players]);

  const translateGender = (gender: Gender) => gender === Gender.MALE ? 'Masculino' : 'Feminino';

  const resetDailyMatches = () => {
    if (window.confirm('Deseja zerar as partidas de hoje para todos os jogadores?')) {
      setPlayers(prev => prev.map(p => ({ ...p, dailyMatches: 0 })));
      setAttendance(prev => prev.map(p => ({ ...p, dailyMatches: 0 })));
      alert('Contador diário resetado.');
    }
  };

  // --- Lógica de Sócios ---
  const savePlayer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const playerData: Player = {
      id: editingPlayer?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      gender: formData.get('gender') as Gender,
      isOfficialSetter: formData.get('isOfficialSetter') === 'on',
      elo: parseInt(formData.get('elo') as string) || 1200,
      matchesPlayed: parseInt(formData.get('matchesPlayed') as string) || 0,
      dailyMatches: editingPlayer?.dailyMatches || 0,
      wins: editingPlayer?.wins || 0,
      losses: editingPlayer?.losses || 0,
    };

    if (editingPlayer) {
      setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? playerData : p));
    } else {
      setPlayers(prev => [...prev, playerData]);
    }

    setIsFormOpen(false);
    setEditingPlayer(null);
  };

  const deletePlayer = (id: string) => {
    if (window.confirm('Deseja excluir este sócio?')) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setAttendance(prev => prev.filter(p => p.id !== id));
    }
  };

  // --- Lógica de Troca de Jogadores ---
  const handleSwapClick = (team: 'A' | 'B', playerId: string) => {
    if (!swapSelection) {
      setSwapSelection({ team, playerId });
    } else {
      if (swapSelection.team === team) {
        setSwapSelection({ team, playerId });
      } else {
        performSwap(swapSelection.playerId, playerId);
        setSwapSelection(null);
      }
    }
  };

  const performSwap = (id1: string, id2: string) => {
    if (!generationResult) return;

    const findAndReplace = (team: Team, oldId: string, newPlayer: Player) => {
      if (team.setter?.id === oldId) {
        return { ...team, setter: newPlayer };
      }
      return {
        ...team,
        players: team.players.map(p => p.id === oldId ? newPlayer : p)
      };
    };

    const p1 = [...players, ...attendance].find(p => p.id === id1)!;
    const p2 = [...players, ...attendance].find(p => p.id === id2)!;

    const newTeamA = findAndReplace(generationResult.teamA, id1, p2);
    const newTeamB = findAndReplace(generationResult.teamB, id2, p1);

    const calcElo = (t: Team) => (t.players.reduce((s, p) => s + p.elo, 0) + (t.setter?.elo || 0));

    setGenerationResult({
      ...generationResult,
      teamA: { ...newTeamA, totalElo: calcElo(newTeamA) },
      teamB: { ...newTeamB, totalElo: calcElo(newTeamB) }
    });
  };

  // --- Lógica de Encerramento de Partida ---
  const handleMatchWinner = (winner: 'A' | 'B') => {
    if (!generationResult) return;

    const teamAPlayers = [generationResult.teamA.setter, ...generationResult.teamA.players].filter(Boolean) as Player[];
    const teamBPlayers = [generationResult.teamB.setter, ...generationResult.teamB.players].filter(Boolean) as Player[];
    const allMatchPlayers = [...teamAPlayers, ...teamBPlayers];

    const winningPlayers = winner === 'A' ? teamAPlayers : teamBPlayers;
    const losingPlayers = winner === 'A' ? teamBPlayers : teamAPlayers;

    setPlayers(prev => prev.map(p => {
      const isWinner = winningPlayers.some(wp => wp.id === p.id);
      const isLoser = losingPlayers.some(lp => lp.id === p.id);
      const playedInMatch = allMatchPlayers.some(mp => mp.id === p.id);

      if (isWinner) {
        return { 
          ...p, 
          elo: p.elo + 25, 
          wins: p.wins + 1, 
          matchesPlayed: p.matchesPlayed + 1,
          dailyMatches: p.dailyMatches + 1
        };
      }
      if (isLoser) {
        return { 
          ...p, 
          elo: Math.max(0, p.elo - 20), 
          losses: p.losses + 1, 
          matchesPlayed: p.matchesPlayed + 1,
          dailyMatches: p.dailyMatches + 1
        };
      }
      // Se estava na lista de presença mas não jogou esta partida, não altera nada aqui
      return p;
    }));

    // Também atualizamos a lista de presença (attendance) para refletir o aumento de partidas jogadas
    setAttendance(prev => prev.map(p => {
      if (allMatchPlayers.some(mp => mp.id === p.id)) {
        return { ...p, dailyMatches: p.dailyMatches + 1 };
      }
      return p;
    }));

    alert(`Partida registrada! Vitória do Time ${winner}.`);
    setGenerationResult(null);
    setAnalysis('');
  };

  // --- Lógica de Partida ---
  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("É necessário pelo menos 10 jogadores para uma partida!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  // --- Renderização do Dashboard ---
  const renderDashboard = () => {
    const sortedRanking = [...players].sort((a, b) => b.elo - a.elo);
    const avgElo = players.length ? Math.round(players.reduce((acc, p) => acc + p.elo, 0) / players.length) : 0;

    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-50 text-indigo-600 rounded-xl"><TrendingUp className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">ELO Médio</p><p className="text-2xl font-black">{avgElo}</p></div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-rose-50 text-rose-600 rounded-xl"><History className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">Sócios Ativos</p><p className="text-2xl font-black">{players.length}</p></div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><Medal className="w-6 h-6"/></div>
              <div><p className="text-xs font-bold text-slate-400 uppercase">Líder Atual</p><p className="text-2xl font-black truncate max-w-[150px]">{sortedRanking[0]?.name || '-'}</p></div>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <BarChart3 className="text-indigo-600 w-5 h-5"/>
              <h3 className="font-bold text-lg">Ranking de Performance</h3>
            </div>
            <button onClick={resetDailyMatches} className="text-xs flex items-center gap-1.5 font-bold text-rose-600 hover:bg-rose-50 px-3 py-1.5 rounded-lg transition-colors">
              <RotateCcw className="w-3.5 h-3.5"/>
              Resetar Dia
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                <tr>
                  <th className="px-6 py-4">Posição</th>
                  <th className="px-6 py-4">Nome</th>
                  <th className="px-6 py-4 text-center">Jogos Hoje</th>
                  <th className="px-6 py-4 text-center">Vitórias</th>
                  <th className="px-6 py-4 text-center">Win Rate</th>
                  <th className="px-6 py-4 text-right">ELO</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {sortedRanking.slice(0, 15).map((p, idx) => {
                  const winRate = p.matchesPlayed > 0 ? Math.round((p.wins / p.matchesPlayed) * 100) : 0;
                  return (
                    <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4">
                        <span className={`w-7 h-7 flex items-center justify-center rounded-lg font-bold text-xs ${idx === 0 ? 'bg-amber-100 text-amber-700' : idx === 1 ? 'bg-slate-200 text-slate-700' : idx === 2 ? 'bg-orange-100 text-orange-700' : 'text-slate-400'}`}>
                          {idx + 1}
                        </span>
                      </td>
                      <td className="px-6 py-4 font-bold text-slate-900">{p.name}</td>
                      <td className="px-6 py-4 text-center">
                        <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${p.dailyMatches > 0 ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}`}>
                          {p.dailyMatches}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-center text-indigo-600 font-semibold">{p.wins}</td>
                      <td className="px-6 py-4 text-center">
                        <span className="text-[10px] font-bold text-slate-400">{winRate}%</span>
                      </td>
                      <td className="px-6 py-4 text-right font-mono font-bold text-indigo-600">{p.elo}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">SpikeGen</h1>
          </div>

          <nav className="hidden md:flex items-center bg-slate-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('match')} className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'match' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>Dia do Jogo</button>
            <button onClick={() => setViewMode('members')} className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'members' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>Gestão de Sócios</button>
            <button onClick={() => setViewMode('dashboard')} className={`px-4 py-1.5 rounded-lg text-sm font-semibold transition-all ${viewMode === 'dashboard' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>Dashboard</button>
          </nav>

          <div className="flex items-center space-x-4 text-sm text-slate-500 font-medium">
            <Calendar className="w-4 h-4" />
            <span className="hidden sm:inline uppercase text-[10px] font-black tracking-widest">{new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'short' })}</span>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 flex-grow w-full">
        {viewMode === 'match' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-4 space-y-6">
              <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                  <h2 className="font-semibold flex items-center gap-2 text-slate-700"><Users className="w-4 h-4 text-indigo-600" />Lista de Presença ({attendance.length})</h2>
                  <button onClick={resetDailyMatches} title="Resetar partidas diárias" className="p-1.5 text-slate-400 hover:text-rose-600 transition-colors"><RotateCcw className="w-4 h-4"/></button>
                </div>
                <div className="p-4 space-y-2 max-h-[500px] overflow-y-auto">
                  {attendance.length === 0 ? (
                    <div className="text-center py-12 text-slate-300 italic text-sm">Nenhum sócio na fila. Clique nos disponíveis abaixo!</div>
                  ) : (
                    attendance.map((player) => (
                      <div key={player.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-xl group border border-slate-100 hover:bg-white hover:border-indigo-100 transition-all">
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-indigo-300">#{player.arrivalOrder}</span>
                          <div>
                            <p className="text-sm font-bold text-slate-800">{player.name}</p>
                            <div className="flex items-center gap-2">
                              <span className="text-[10px] font-black uppercase text-indigo-600 bg-indigo-50 px-1.5 rounded">Jogos: {player.dailyMatches}</span>
                              <span className="text-[10px] text-slate-400 uppercase font-bold">{player.elo} ELO</span>
                            </div>
                          </div>
                        </div>
                        <button onClick={() => removeAttendance(player.id)} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"><X className="w-4 h-4" /></button>
                      </div>
                    ))
                  )}
                </div>
                <div className="p-4 bg-slate-50 border-t border-slate-200">
                  <button onClick={handleGenerate} disabled={attendance.length < 10} className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-black py-4 rounded-2xl shadow-xl shadow-indigo-100 transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-sm">
                    Gerar Times da Partida
                    <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              </section>

              <section className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 border-b border-slate-200"><h2 className="font-semibold text-[10px] uppercase text-slate-500 font-black tracking-widest">Sócios Disponíveis</h2></div>
                <div className="p-2 grid grid-cols-1 gap-1 max-h-[300px] overflow-y-auto">
                  {availablePlayers.length === 0 ? (
                    <div className="p-4 text-center text-slate-300 text-xs italic">Nenhum sócio restante.</div>
                  ) : (
                    availablePlayers.map(player => (
                      <button key={player.id} onClick={() => registerAttendance(player)} className="flex items-center justify-between p-3 rounded-xl hover:bg-indigo-50 transition-colors text-left group">
                        <div><p className="text-sm font-medium text-slate-700">{player.name}</p><p className="text-[10px] text-slate-400 uppercase font-bold">Hoje: {player.dailyMatches} • ELO {player.elo}</p></div>
                        <Plus className="w-4 h-4 text-indigo-300 group-hover:text-indigo-600" />
                      </button>
                    ))
                  )}
                </div>
              </section>
            </div>

            <div className="lg:col-span-8 space-y-6">
              {!generationResult ? (
                <div className="h-full min-h-[600px] flex flex-col items-center justify-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 space-y-4 text-center px-4">
                  <Trophy className="w-16 h-16 opacity-10" />
                  <div>
                    <p className="text-xl font-black text-slate-400 uppercase tracking-widest">Arena Pronta</p>
                    <p className="text-sm max-w-xs mx-auto">Selecione pelo menos 10 jogadores na lista de presença para gerar as equipes de forma equilibrada.</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-6 animate-in fade-in slide-in-from-top-4 duration-500">
                  {/* Visualização dos Times Gerados */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <TeamCard 
                      title="Time A" 
                      team={generationResult.teamA} 
                      color="indigo" 
                      onSwap={(pid) => handleSwapClick('A', pid)}
                      activeSwapId={swapSelection?.team === 'A' ? swapSelection.playerId : null}
                    />
                    <TeamCard 
                      title="Time B" 
                      team={generationResult.teamB} 
                      color="rose" 
                      onSwap={(pid) => handleSwapClick('B', pid)}
                      activeSwapId={swapSelection?.team === 'B' ? swapSelection.playerId : null}
                    />
                  </div>

                  {/* Registro de Vencedor */}
                  <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl text-center space-y-6 border-4 border-slate-800">
                    <div className="space-y-1">
                      <h3 className="font-black text-white uppercase tracking-[0.2em] text-xs">Fim de Jogo</h3>
                      <p className="text-slate-400 text-sm">Registre o vencedor para atualizar rankings e rotação.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-6">
                      <button 
                        onClick={() => handleMatchWinner('A')}
                        className="bg-indigo-600 text-white py-5 rounded-2xl font-black shadow-lg shadow-indigo-900/50 hover:bg-indigo-500 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
                      >
                        <Check className="w-6 h-6 group-hover:scale-125 transition-transform"/> 
                        <span className="tracking-widest">TIME A VENCEU</span>
                      </button>
                      <button 
                        onClick={() => handleMatchWinner('B')}
                        className="bg-rose-600 text-white py-5 rounded-2xl font-black shadow-lg shadow-rose-900/50 hover:bg-rose-500 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
                      >
                        <Check className="w-6 h-6 group-hover:scale-125 transition-transform"/> 
                        <span className="tracking-widest">TIME B VENCEU</span>
                      </button>
                    </div>
                  </div>

                  {/* Análise IA */}
                  <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="p-5 bg-slate-50 text-slate-900 border-b border-slate-200 flex items-center justify-between">
                      <div className="flex items-center gap-2"><Sparkles className="w-4 h-4 text-indigo-600" /><h3 className="font-bold text-sm uppercase tracking-widest">Análise do Confronto</h3></div>
                      {!analysis && <button onClick={handleAnalyze} disabled={isAnalyzing} className="text-[10px] bg-indigo-600 text-white px-3 py-1.5 rounded-full font-black uppercase tracking-widest hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">{isAnalyzing ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Analisar'}</button>}
                    </div>
                    <div className="p-8">
                      {isAnalyzing ? (
                        <div className="space-y-4">
                          <div className="h-4 bg-slate-100 rounded-full animate-pulse w-3/4"></div>
                          <div className="h-4 bg-slate-100 rounded-full animate-pulse w-full"></div>
                          <div className="h-4 bg-slate-100 rounded-full animate-pulse w-5/6"></div>
                        </div>
                      ) : analysis ? (
                        <p className="text-slate-600 leading-relaxed text-sm italic">"{analysis}"</p>
                      ) : (
                        <div className="text-center py-4">
                          <p className="text-slate-400 text-xs font-medium uppercase tracking-widest">Clique em Analisar para obter insights táticos</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        ) : viewMode === 'members' ? (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Gestão de Sócios</h2><button onClick={() => { setEditingPlayer(null); setIsFormOpen(true); }} className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg"><UserPlus className="w-5 h-5" />Novo Sócio</button></div>
            <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr><th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nome</th><th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Levantador</th><th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Partidas Hoje</th><th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">ELO</th><th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {players.sort((a,b) => a.name.localeCompare(b.name)).map(player => (
                    <tr key={player.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-4 font-bold text-slate-700">{player.name}</td>
                      <td className="px-6 py-4 text-center">{player.isOfficialSetter ? <span className="bg-amber-100 text-amber-700 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">Oficial</span> : <span className="text-slate-300">-</span>}</td>
                      <td className="px-6 py-4 text-center font-bold text-indigo-600">{player.dailyMatches}</td>
                      <td className="px-6 py-4 text-center font-mono text-sm font-bold">{player.elo}</td>
                      <td className="px-6 py-4 text-right flex justify-end gap-2"><button onClick={() => { setEditingPlayer(player); setIsFormOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit2 className="w-4 h-4" /></button><button onClick={() => deletePlayer(player.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg"><Trash2 className="w-4 h-4" /></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          renderDashboard()
        )}
      </main>

      {/* Modal de Sócio */}
      {isFormOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[2rem] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50"><h3 className="text-lg font-black uppercase tracking-widest text-slate-800">{editingPlayer ? 'Editar Sócio' : 'Novo Sócio'}</h3><button onClick={() => setIsFormOpen(false)}><X className="w-5 h-5 text-slate-400 hover:text-slate-600" /></button></div>
            <form onSubmit={savePlayer} className="p-8 space-y-6">
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome Completo</label><input name="name" required defaultValue={editingPlayer?.name} className="w-full px-5 py-3 rounded-2xl border border-slate-200 outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-400 transition-all font-bold text-slate-700" /></div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gênero</label><select name="gender" defaultValue={editingPlayer?.gender || Gender.MALE} className="w-full px-5 py-3 rounded-2xl border border-slate-200 font-bold text-slate-700"><option value={Gender.MALE}>Masculino</option><option value={Gender.FEMALE}>Feminino</option></select></div>
                <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Pontuação ELO</label><input name="elo" type="number" required defaultValue={editingPlayer?.elo || 1200} className="w-full px-5 py-3 rounded-2xl border border-slate-200 font-bold text-slate-700" /></div>
              </div>
              <div className="flex items-center gap-4 p-5 bg-amber-50 rounded-[1.5rem] border border-amber-100"><input id="setter-check" name="isOfficialSetter" type="checkbox" defaultChecked={editingPlayer?.isOfficialSetter} className="w-6 h-6 rounded-lg text-amber-600 focus:ring-amber-500 border-amber-200" /><label htmlFor="setter-check" className="text-sm font-black text-amber-900 uppercase tracking-widest cursor-pointer">Levantador Oficial</label></div>
              <div className="pt-4 flex gap-4"><button type="button" onClick={() => setIsFormOpen(false)} className="flex-1 px-4 py-4 font-black text-slate-400 uppercase tracking-widest text-xs">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white px-4 py-4 rounded-2xl font-black flex items-center justify-center gap-2 shadow-xl shadow-indigo-100 uppercase tracking-widest text-xs">Salvar Sócio</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// Componente TeamCard
const TeamCard: React.FC<{ 
  title: string; 
  team: any; 
  color: 'indigo' | 'rose'; 
  onSwap: (pid: string) => void;
  activeSwapId: string | null;
}> = ({ title, team, color, onSwap, activeSwapId }) => {
  const colorClass = color === 'indigo' ? 'bg-indigo-600' : 'bg-rose-600';
  const textClass = color === 'indigo' ? 'text-indigo-600' : 'text-rose-600';
  const bgHeader = color === 'indigo' ? 'bg-indigo-500' : 'bg-rose-500';

  const PlayerRow = ({ p, isSetter = false }: { p: Player | null, isSetter?: boolean }) => {
    if (!p) return null;
    const isActive = activeSwapId === p.id;

    return (
      <div className={`flex justify-between items-center p-3.5 rounded-2xl transition-all border-2 ${isActive ? 'border-indigo-500 bg-indigo-50 scale-105 shadow-xl z-10' : 'border-transparent bg-slate-50 hover:bg-white hover:shadow-md'}`}>
        <div className="flex items-center gap-3">
          <div className={`w-3 h-3 rounded-full border-2 border-white ${p.gender === Gender.MALE ? 'bg-blue-400' : 'bg-pink-400'}`}></div>
          <div>
            <span className="text-sm font-black text-slate-700 block tracking-tight">{p.name}</span>
            <div className="flex items-center gap-2">
              <span className="text-[9px] font-black uppercase text-indigo-500 bg-indigo-50 px-1 rounded">Hoje: {p.dailyMatches}</span>
              <span className="text-[9px] text-slate-400 font-bold uppercase">ELO: {p.elo}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {isSetter && <span className="text-[8px] font-black text-amber-600 bg-amber-100 px-1.5 py-0.5 rounded tracking-widest uppercase">Levant</span>}
          <button 
            onClick={() => onSwap(p.id)}
            className={`p-2 rounded-xl transition-all ${isActive ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:text-indigo-600 hover:bg-indigo-50'}`}
          >
            <ArrowLeftRight className="w-4 h-4"/>
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl overflow-hidden flex flex-col h-full transition-all hover:border-slate-300">
      <div className={`p-6 ${colorClass} text-white`}>
        <div className="flex justify-between items-center mb-1">
          <p className="text-[10px] font-black uppercase opacity-60 tracking-[0.2em]">Escalação</p>
          <p className="text-[10px] font-black uppercase opacity-60 tracking-[0.2em]">Equilíbrio ELO</p>
        </div>
        <div className="flex justify-between items-end">
          <h3 className="font-black text-3xl tracking-tighter uppercase">{title}</h3>
          <p className="text-4xl font-black tracking-tighter">{team.totalElo}</p>
        </div>
      </div>

      <div className="p-6 space-y-6 flex-grow">
        <div className="space-y-3">
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] px-1">Distribuidor Oficial</h4>
          {team.setter ? (
            <PlayerRow p={team.setter} isSetter />
          ) : (
            <div className="p-5 rounded-2xl border-2 border-dashed border-slate-100 bg-slate-50 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Definir Temporário</p>
            </div>
          )}
        </div>

        <div className="space-y-3">
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] px-1">Unidades de Ataque</h4>
          <div className="grid grid-cols-1 gap-2.5">
            {team.players.map((p: Player) => (
              <PlayerRow key={p.id} p={p} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { INITIAL_PLAYERS } from './constants';
import { Player, Gender, GenerationResult, Team } from './types';
import { generateTeams } from './utils/teamLogic';
import { analyzeMatch } from './services/geminiService';
import { 
  Users, 
  Trophy, 
  Calendar, 
  ArrowRight, 
  Plus, 
  Sparkles,
  RefreshCw,
  LogOut,
  Edit2,
  Trash2,
  Save,
  X,
  UserPlus,
  BarChart3,
  TrendingUp,
  History,
  ArrowLeftRight,
  Medal,
  Check,
  RotateCcw,
  LayoutDashboard,
  ClipboardCheck,
  Swords
} from 'lucide-react';

type ViewMode = 'presence' | 'generation' | 'members' | 'dashboard';

const App: React.FC = () => {
  // --- Estados Principais ---
  const [players, setPlayers] = useState<Player[]>(() => {
    const saved = localStorage.getItem('spikegen_players_v4');
    if (saved) return JSON.parse(saved);
    return INITIAL_PLAYERS.map(p => ({ ...p, dailyMatches: 0 }));
  });

  const [viewMode, setViewMode] = useState<ViewMode>('presence');
  const [attendance, setAttendance] = useState<Player[]>([]);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // --- Estados de Gestão ---
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [swapSelection, setSwapSelection] = useState<{ team: 'A' | 'B'; playerId: string } | null>(null);

  // --- Persistência ---
  useEffect(() => {
    localStorage.setItem('spikegen_players_v4', JSON.stringify(players));
  }, [players]);

  const translateGender = (gender: Gender) => gender === Gender.MALE ? 'Masculino' : 'Feminino';

  const resetDailyMatches = () => {
    if (window.confirm('Deseja zerar as partidas de hoje para todos os jogadores?')) {
      const reset = (p: Player) => ({ ...p, dailyMatches: 0 });
      setPlayers(prev => prev.map(reset));
      setAttendance(prev => prev.map(reset));
      alert('Contador diário resetado.');
    }
  };

  // --- Lógica de Sócios ---
  const savePlayer = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const playerData: Player = {
      id: editingPlayer?.id || crypto.randomUUID(),
      name: formData.get('name') as string,
      gender: formData.get('gender') as Gender,
      isOfficialSetter: formData.get('isOfficialSetter') === 'on',
      elo: parseInt(formData.get('elo') as string) || 1200,
      matchesPlayed: parseInt(formData.get('matchesPlayed') as string) || 0,
      dailyMatches: editingPlayer?.dailyMatches || 0,
      wins: editingPlayer?.wins || 0,
      losses: editingPlayer?.losses || 0,
    };

    if (editingPlayer) {
      setPlayers(prev => prev.map(p => p.id === editingPlayer.id ? playerData : p));
    } else {
      setPlayers(prev => [...prev, playerData]);
    }

    setIsFormOpen(false);
    setEditingPlayer(null);
  };

  const deletePlayer = (id: string) => {
    if (window.confirm('Deseja excluir este sócio?')) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setAttendance(prev => prev.filter(p => p.id !== id));
    }
  };

  // --- Lógica de Troca de Jogadores ---
  const handleSwapClick = (team: 'A' | 'B', playerId: string) => {
    if (!swapSelection) {
      setSwapSelection({ team, playerId });
    } else {
      if (swapSelection.team === team) {
        setSwapSelection({ team, playerId });
      } else {
        performSwap(swapSelection.playerId, playerId);
        setSwapSelection(null);
      }
    }
  };

  const performSwap = (id1: string, id2: string) => {
    if (!generationResult) return;

    const findAndReplace = (team: Team, oldId: string, newPlayer: Player) => {
      if (team.setter?.id === oldId) return { ...team, setter: newPlayer };
      return { ...team, players: team.players.map(p => p.id === oldId ? newPlayer : p) };
    };

    const p1 = [...players, ...attendance].find(p => p.id === id1)!;
    const p2 = [...players, ...attendance].find(p => p.id === id2)!;

    const newTeamA = findAndReplace(generationResult.teamA, id1, p2);
    const newTeamB = findAndReplace(generationResult.teamB, id2, p1);

    const calcElo = (t: Team) => (t.players.reduce((s, p) => s + p.elo, 0) + (t.setter?.elo || 0));

    setGenerationResult({
      ...generationResult,
      teamA: { ...newTeamA, totalElo: calcElo(newTeamA) },
      teamB: { ...newTeamB, totalElo: calcElo(newTeamB) }
    });
  };

  // --- Lógica de Encerramento ---
  const handleMatchWinner = (winner: 'A' | 'B') => {
    if (!generationResult) return;

    const teamAPlayers = [generationResult.teamA.setter, ...generationResult.teamA.players].filter(Boolean) as Player[];
    const teamBPlayers = [generationResult.teamB.setter, ...generationResult.teamB.players].filter(Boolean) as Player[];
    const allMatchPlayers = [...teamAPlayers, ...teamBPlayers];

    const winningPlayers = winner === 'A' ? teamAPlayers : teamBPlayers;
    const losingPlayers = winner === 'A' ? teamBPlayers : teamAPlayers;

    const updatePlayer = (p: Player) => {
      const isWinner = winningPlayers.some(wp => wp.id === p.id);
      const isLoser = losingPlayers.some(lp => lp.id === p.id);
      if (isWinner) return { ...p, elo: p.elo + 25, wins: p.wins + 1, matchesPlayed: p.matchesPlayed + 1, dailyMatches: p.dailyMatches + 1 };
      if (isLoser) return { ...p, elo: Math.max(0, p.elo - 20), losses: p.losses + 1, matchesPlayed: p.matchesPlayed + 1, dailyMatches: p.dailyMatches + 1 };
      return p;
    };

    setPlayers(prev => prev.map(updatePlayer));
    setAttendance(prev => prev.map(p => {
      if (allMatchPlayers.some(mp => mp.id === p.id)) {
        return { ...p, dailyMatches: p.dailyMatches + 1 };
      }
      return p;
    }));

    alert(`Sucesso! Vitória do Time ${winner}. ELOs atualizados.`);
    setGenerationResult(null);
    setAnalysis('');
    setViewMode('presence');
  };

  // --- Lógica de Presença ---
  const registerAttendance = useCallback((player: Player) => {
    if (attendance.some(p => p.id === player.id)) return;
    setAttendance(prev => [...prev, { ...player, arrivalOrder: prev.length + 1 }]);
  }, [attendance]);

  const removeAttendance = useCallback((playerId: string) => {
    setAttendance(prev => prev.filter(p => p.id !== playerId).map((p, idx) => ({ ...p, arrivalOrder: idx + 1 })));
  }, []);

  const handleGenerate = () => {
    if (attendance.length < 10) {
      alert("Mínimo de 10 jogadores na lista!");
      return;
    }
    const result = generateTeams(attendance);
    setGenerationResult(result);
    setAnalysis('');
    setViewMode('generation');
  };

  const handleAnalyze = async () => {
    if (!generationResult) return;
    setIsAnalyzing(true);
    const result = await analyzeMatch(generationResult.teamA, generationResult.teamB);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const availablePlayers = useMemo(() => {
    return players.filter(p => !attendance.some(a => a.id === p.id))
      .sort((a, b) => b.elo - a.elo);
  }, [players, attendance]);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header Profissional */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-200">
              <Trophy className="text-white w-5 h-5" />
            </div>
            <div>
              <h1 className="text-lg font-black text-slate-900 leading-none">SpikeGen</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Volleyball Club</p>
            </div>
          </div>

          <nav className="hidden lg:flex items-center bg-slate-100 p-1 rounded-2xl border border-slate-200">
            {[
              { id: 'presence', label: 'Presença', icon: ClipboardCheck },
              { id: 'generation', label: 'Partida', icon: Swords },
              { id: 'members', label: 'Sócios', icon: Users },
              { id: 'dashboard', label: 'Estatísticas', icon: LayoutDashboard },
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setViewMode(tab.id as ViewMode)} 
                className={`flex items-center gap-2 px-5 py-2 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${viewMode === tab.id ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
              >
                <tab.icon className="w-3.5 h-3.5" />
                {tab.label}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
             <div className="hidden sm:flex flex-col items-end">
               <span className="text-[10px] font-black text-slate-400 uppercase">{new Date().toLocaleDateString('pt-BR', { weekday: 'long' })}</span>
               <span className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('pt-BR')}</span>
             </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 flex-grow w-full">
        {/* VIEW: PRESENÇA */}
        {viewMode === 'presence' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="lg:col-span-4 space-y-6">
              <section className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-6 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
                  <div>
                    <h2 className="font-black text-slate-800 uppercase text-xs tracking-widest flex items-center gap-2"><ClipboardCheck className="w-4 h-4 text-indigo-600" />Lista de Presença</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">{attendance.length} confirmados</p>
                  </div>
                  <button onClick={resetDailyMatches} title="Zerar partidas do dia" className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"><RotateCcw className="w-4 h-4"/></button>
                </div>
                <div className="p-4 space-y-2 max-h-[500px] overflow-y-auto">
                  {attendance.length === 0 ? (
                    <div className="text-center py-16">
                      <Users className="w-12 h-12 text-slate-100 mx-auto mb-4" />
                      <p className="text-slate-300 text-sm italic">Ninguém confirmou ainda...</p>
                    </div>
                  ) : (
                    attendance.map((player) => (
                      <div key={player.id} className="flex items-center justify-between bg-white p-4 rounded-2xl border border-slate-100 hover:border-indigo-100 hover:shadow-md transition-all group">
                        <div className="flex items-center gap-4">
                          <span className="text-[10px] font-black text-indigo-300 w-4">#{player.arrivalOrder}</span>
                          <div>
                            <p className="text-sm font-black text-slate-700">{player.name}</p>
                            <div className="flex items-center gap-2">
                              <span className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded">Hoje: {player.dailyMatches}</span>
                              <span className="text-[9px] text-slate-400 font-bold uppercase">ELO {player.elo}</span>
                            </div>
                          </div>
                        </div>
                        <button onClick={() => removeAttendance(player.id)} className="p-2 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"><X className="w-4 h-4" /></button>
                      </div>
                    ))
                  )}
                </div>
                <div className="p-6 bg-slate-50 border-t border-slate-200">
                  <button 
                    onClick={handleGenerate} 
                    disabled={attendance.length < 10} 
                    className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-black py-5 rounded-2xl shadow-xl shadow-indigo-100 transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-xs"
                  >
                    Escalar Partida <ArrowRight className="w-4 h-4" />
                  </button>
                </div>
              </section>
            </div>

            <div className="lg:col-span-8 space-y-6">
              <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Sócios Disponíveis</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {availablePlayers.length === 0 ? (
                    <div className="col-span-full py-20 text-center">
                      <p className="text-slate-300 text-sm italic">Todos os sócios já confirmaram presença!</p>
                    </div>
                  ) : (
                    availablePlayers.map(player => (
                      <button 
                        key={player.id} 
                        onClick={() => registerAttendance(player)} 
                        className="flex items-center justify-between p-5 rounded-2xl border border-slate-50 hover:border-indigo-100 hover:bg-indigo-50/30 transition-all text-left group"
                      >
                        <div>
                          <p className="text-sm font-black text-slate-700">{player.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Jogos Hoje: {player.dailyMatches} • {player.elo} ELO</p>
                        </div>
                        <div className="p-2 bg-slate-50 text-slate-300 group-hover:bg-indigo-600 group-hover:text-white rounded-xl transition-all"><Plus className="w-4 h-4" /></div>
                      </button>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* VIEW: GERAÇÃO (A QUADRA) */}
        {viewMode === 'generation' && (
          <div className="space-y-8 animate-in zoom-in-95 duration-500">
            {!generationResult ? (
              <div className="h-[500px] flex flex-col items-center justify-center text-center space-y-6 bg-white rounded-[3rem] border-4 border-dashed border-slate-100">
                <Swords className="w-20 h-20 text-slate-100" />
                <div className="space-y-2">
                  <p className="text-xl font-black text-slate-400 uppercase tracking-widest">Nenhuma Partida Escalada</p>
                  <p className="text-sm text-slate-300 max-w-xs mx-auto">Vá na aba Presença e selecione os jogadores para ver o confronto aqui.</p>
                </div>
                <button onClick={() => setViewMode('presence')} className="text-xs font-black uppercase text-indigo-600 bg-indigo-50 px-6 py-3 rounded-full hover:bg-indigo-100 transition-all tracking-widest">Voltar para Presença</button>
              </div>
            ) : (
              <>
                <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-2">
                  <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter flex items-center gap-3">
                    <Swords className="w-8 h-8 text-indigo-600" /> Confronto Equilibrado
                  </h2>
                  <div className="flex gap-2">
                    <button onClick={() => setGenerationResult(null)} className="text-[10px] font-black uppercase text-slate-400 hover:text-rose-600 px-4 py-2">Descartar</button>
                    <button onClick={handleGenerate} className="text-[10px] font-black uppercase bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 px-6 py-2 rounded-xl shadow-sm">Nova Escalação</button>
                  </div>
                </div>

                {swapSelection && (
                  <div className="bg-amber-100 border-2 border-amber-200 p-5 rounded-3xl flex items-center justify-between animate-pulse">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-amber-200 rounded-xl"><ArrowLeftRight className="w-5 h-5 text-amber-700" /></div>
                      <p className="text-amber-900 text-xs font-black uppercase tracking-widest">Troca Ativa: Selecione o oponente para trocar de time</p>
                    </div>
                    <button onClick={() => setSwapSelection(null)} className="text-[10px] font-black uppercase text-amber-900 underline">Cancelar</button>
                  </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <TeamCard 
                    title="Time A" 
                    team={generationResult.teamA} 
                    color="indigo" 
                    onSwap={(pid) => handleSwapClick('A', pid)}
                    activeSwapId={swapSelection?.team === 'A' ? swapSelection.playerId : null}
                  />
                  <TeamCard 
                    title="Time B" 
                    team={generationResult.teamB} 
                    color="rose" 
                    onSwap={(pid) => handleSwapClick('B', pid)}
                    activeSwapId={swapSelection?.team === 'B' ? swapSelection.playerId : null}
                  />
                </div>

                <div className="bg-slate-900 p-10 rounded-[3rem] shadow-2xl border-4 border-slate-800 text-center space-y-8 relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-rose-500"></div>
                  <div className="space-y-2">
                    <h3 className="text-white font-black uppercase tracking-[0.3em] text-xs">Finalização da Partida</h3>
                    <p className="text-slate-400 text-sm max-w-sm mx-auto font-medium">O resultado irá atualizar o ELO global e aumentar o contador diário dos participantes.</p>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-2xl mx-auto">
                    <button 
                      onClick={() => handleMatchWinner('A')}
                      className="group bg-indigo-600 hover:bg-indigo-500 text-white py-6 rounded-2xl font-black shadow-2xl shadow-indigo-900/50 transition-all flex items-center justify-center gap-4 hover:scale-105 active:scale-95"
                    >
                      <Check className="w-6 h-6 group-hover:scale-125 transition-transform" /> 
                      <span className="tracking-widest uppercase text-sm">Vitória Time A</span>
                    </button>
                    <button 
                      onClick={() => handleMatchWinner('B')}
                      className="group bg-rose-600 hover:bg-rose-500 text-white py-6 rounded-2xl font-black shadow-2xl shadow-rose-900/50 transition-all flex items-center justify-center gap-4 hover:scale-105 active:scale-95"
                    >
                      <Check className="w-6 h-6 group-hover:scale-125 transition-transform" /> 
                      <span className="tracking-widest uppercase text-sm">Vitória Time B</span>
                    </button>
                  </div>
                </div>

                <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden">
                  <div className="p-6 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                    <div className="flex items-center gap-3"><Sparkles className="w-5 h-5 text-indigo-500" /><h3 className="font-black text-xs uppercase tracking-widest">Análise de IA</h3></div>
                    {!analysis && <button onClick={handleAnalyze} disabled={isAnalyzing} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-5 py-2 rounded-full hover:bg-indigo-700 transition-all">{isAnalyzing ? <RefreshCw className="w-3 h-3 animate-spin" /> : 'Solicitar Insight'}</button>}
                  </div>
                  <div className="p-10">
                    {analysis ? (
                      <div className="relative">
                        <span className="text-6xl text-slate-100 absolute -top-4 -left-4 font-serif">“</span>
                        <p className="text-slate-600 text-base leading-relaxed font-medium italic relative z-10">{analysis}</p>
                      </div>
                    ) : isAnalyzing ? (
                      <div className="space-y-4 animate-pulse">
                        <div className="h-4 bg-slate-100 rounded-full w-3/4"></div>
                        <div className="h-4 bg-slate-100 rounded-full w-full"></div>
                        <div className="h-4 bg-slate-100 rounded-full w-5/6"></div>
                      </div>
                    ) : (
                      <div className="text-center py-4"><p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Aguardando solicitação de análise tática...</p></div>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>
        )}

        {/* VIEW: SÓCIOS */}
        {viewMode === 'members' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Gestão da Base</h2>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Total de {players.length} sócios cadastrados</p>
              </div>
              <button onClick={() => { setEditingPlayer(null); setIsFormOpen(true); }} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all"><UserPlus className="w-5 h-5" />Novo Sócio</button>
            </div>
            <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Sócio</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Posição</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Gênero</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">ELO Rank</th>
                    <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {players.sort((a,b) => a.name.localeCompare(b.name)).map(player => (
                    <tr key={player.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-8 py-5">
                        <p className="font-black text-slate-700">{player.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">{player.matchesPlayed} partidas totais</p>
                      </td>
                      <td className="px-8 py-5 text-center">
                        {player.isOfficialSetter ? (
                          <span className="bg-amber-100 text-amber-700 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">Levantador</span>
                        ) : (
                          <span className="text-slate-300 font-bold text-xs">-</span>
                        )}
                      </td>
                      <td className="px-8 py-5 text-center text-[10px] font-bold text-slate-500 uppercase">{translateGender(player.gender)}</td>
                      <td className="px-8 py-5 text-center font-mono text-sm font-black text-indigo-600">{player.elo}</td>
                      <td className="px-8 py-5 text-right">
                        <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setEditingPlayer(player); setIsFormOpen(true); }} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><Edit2 className="w-4 h-4" /></button>
                          <button onClick={() => deletePlayer(player.id)} className="p-2.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"><Trash2 className="w-4 h-4" /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* VIEW: DASHBOARD */}
        {viewMode === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-6">
                 <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><TrendingUp className="w-8 h-8"/></div>
                 <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">ELO Médio Clube</p><p className="text-3xl font-black text-slate-900">{players.length ? Math.round(players.reduce((s, p) => s + p.elo, 0) / players.length) : 0}</p></div>
               </div>
               <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-6">
                 <div className="p-4 bg-rose-50 text-rose-600 rounded-2xl"><History className="w-8 h-8"/></div>
                 <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Jogadores Ativos</p><p className="text-3xl font-black text-slate-900">{players.length}</p></div>
               </div>
               <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-6">
                 <div className="p-4 bg-amber-50 text-amber-600 rounded-2xl"><Medal className="w-8 h-8"/></div>
                 <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Mestre do ELO</p><p className="text-xl font-black text-slate-900 truncate max-w-[140px]">{[...players].sort((a,b)=>b.elo-a.elo)[0]?.name || '---'}</p></div>
               </div>
             </div>

             <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
                  <div className="flex items-center gap-3"><BarChart3 className="text-indigo-600 w-6 h-6"/><h3 className="font-black text-lg uppercase tracking-tighter">Quadro de Líderes</h3></div>
                  <button onClick={resetDailyMatches} className="flex items-center gap-2 text-[10px] font-black uppercase text-rose-600 hover:bg-rose-50 px-5 py-2.5 rounded-xl transition-all border border-rose-100"><RotateCcw className="w-3.5 h-3.5"/>Reset Diário</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase">
                      <tr>
                        <th className="px-8 py-5">#</th>
                        <th className="px-8 py-5">Jogador</th>
                        <th className="px-8 py-5 text-center">V / D</th>
                        <th className="px-8 py-5 text-center">Partidas Hoje</th>
                        <th className="px-8 py-5 text-center">Win Rate</th>
                        <th className="px-8 py-5 text-right">Pontuação ELO</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {[...players].sort((a,b) => b.elo - a.elo).slice(0, 15).map((p, idx) => {
                        const winRate = p.matchesPlayed > 0 ? Math.round((p.wins / p.matchesPlayed) * 100) : 0;
                        return (
                          <tr key={p.id} className="hover:bg-slate-50/50 transition-colors">
                            <td className="px-8 py-5">
                              <span className={`w-8 h-8 flex items-center justify-center rounded-xl font-black text-xs ${idx === 0 ? 'bg-amber-100 text-amber-700 shadow-sm' : idx === 1 ? 'bg-slate-100 text-slate-600' : idx === 2 ? 'bg-orange-100 text-orange-700' : 'text-slate-300'}`}>
                                {idx + 1}
                              </span>
                            </td>
                            <td className="px-8 py-5 font-black text-slate-800">{p.name}</td>
                            <td className="px-8 py-5 text-center text-[10px] font-bold">
                               <span className="text-emerald-600">{p.wins}W</span> <span className="text-slate-300">/</span> <span className="text-rose-500">{p.losses}L</span>
                            </td>
                            <td className="px-8 py-5 text-center">
                              <span className={`px-3 py-1 rounded-full text-[10px] font-black ${p.dailyMatches > 0 ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}`}>
                                {p.dailyMatches}
                              </span>
                            </td>
                            <td className="px-8 py-5 text-center">
                              <div className="w-full bg-slate-100 h-1.5 rounded-full max-w-[60px] mx-auto overflow-hidden">
                                <div className="bg-indigo-500 h-full" style={{ width: `${winRate}%` }}></div>
                              </div>
                              <span className="text-[9px] font-black text-slate-400">{winRate}%</span>
                            </td>
                            <td className="px-8 py-5 text-right font-mono font-black text-indigo-600 text-base">{p.elo}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Modal de Formulário Estilizado */}
      {isFormOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in duration-300 border-4 border-white">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-600 rounded-xl text-white"><UserPlus className="w-5 h-5"/></div>
                <h3 className="text-lg font-black uppercase tracking-tighter text-slate-800">{editingPlayer ? 'Editar Sócio' : 'Cadastrar Sócio'}</h3>
              </div>
              <button onClick={() => setIsFormOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="w-5 h-5 text-slate-400" /></button>
            </div>
            <form onSubmit={savePlayer} className="p-10 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome do Jogador</label>
                <input name="name" required defaultValue={editingPlayer?.name} placeholder="Ex: Lucas Silva" className="w-full px-6 py-4 rounded-2xl border border-slate-200 outline-none focus:ring-4 focus:ring-indigo-50 focus:border-indigo-400 transition-all font-bold text-slate-700" />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Gênero</label>
                  <select name="gender" defaultValue={editingPlayer?.gender || Gender.MALE} className="w-full px-6 py-4 rounded-2xl border border-slate-200 font-bold text-slate-700 outline-none focus:border-indigo-400">
                    <option value={Gender.MALE}>Masculino</option>
                    <option value={Gender.FEMALE}>Feminino</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Pontos ELO</label>
                  <input name="elo" type="number" required defaultValue={editingPlayer?.elo || 1200} className="w-full px-6 py-4 rounded-2xl border border-slate-200 font-bold text-slate-700 outline-none focus:border-indigo-400" />
                </div>
              </div>
              <div className="flex items-center gap-5 p-6 bg-amber-50 rounded-[2rem] border border-amber-100 cursor-pointer">
                <input id="setter-check" name="isOfficialSetter" type="checkbox" defaultChecked={editingPlayer?.isOfficialSetter} className="w-6 h-6 rounded-lg text-amber-600 focus:ring-amber-400 border-amber-200 shadow-sm" />
                <label htmlFor="setter-check" className="text-xs font-black text-amber-900 uppercase tracking-widest cursor-pointer select-none">Levantador Oficial</label>
              </div>
              <div className="pt-4 flex gap-4">
                <button type="button" onClick={() => setIsFormOpen(false)} className="flex-1 px-4 py-4 font-black text-slate-400 uppercase tracking-widest text-[10px] hover:text-slate-600 transition-all">Cancelar</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white px-4 py-4 rounded-[1.5rem] font-black flex items-center justify-center gap-2 shadow-xl shadow-indigo-100 uppercase tracking-widest text-[10px] hover:bg-indigo-700 transition-all"><Save className="w-4 h-4" />Salvar Sócio</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// Componente TeamCard
const TeamCard: React.FC<{ 
  title: string; 
  team: any; 
  color: 'indigo' | 'rose'; 
  onSwap: (pid: string) => void;
  activeSwapId: string | null;
}> = ({ title, team, color, onSwap, activeSwapId }) => {
  const colorClass = color === 'indigo' ? 'bg-indigo-600' : 'bg-rose-600';

  const PlayerRow = ({ p, isSetter = false }: { p: Player | null, isSetter?: boolean }) => {
    if (!p) return null;
    const isActive = activeSwapId === p.id;

    return (
      <div className={`flex justify-between items-center p-4 rounded-2xl transition-all border-2 ${isActive ? 'border-indigo-500 bg-indigo-50 scale-105 shadow-xl z-20' : 'border-transparent bg-slate-50 hover:bg-white hover:shadow-md'}`}>
        <div className="flex items-center gap-4">
          <div className={`w-3 h-3 rounded-full border-2 border-white shadow-sm ${p.gender === Gender.MALE ? 'bg-blue-400' : 'bg-pink-400'}`}></div>
          <div>
            <span className="text-sm font-black text-slate-800 block tracking-tight leading-none mb-1">{p.name}</span>
            <div className="flex items-center gap-2">
              <span className="text-[9px] font-black uppercase text-white bg-slate-900 px-1.5 py-0.5 rounded">Partidas hoje: {p.dailyMatches}</span>
              <span className="text-[9px] text-slate-400 font-bold uppercase">ELO: {p.elo}</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {isSetter && <span className="text-[8px] font-black text-amber-700 bg-amber-100 px-2 py-0.5 rounded-full tracking-[0.2em] uppercase">Levant</span>}
          <button 
            onClick={() => onSwap(p.id)}
            className={`p-2.5 rounded-xl transition-all ${isActive ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-300 hover:text-indigo-600 hover:bg-white'}`}
            title="Trocar Jogador"
          >
            <ArrowLeftRight className="w-4 h-4"/>
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-[3rem] border border-slate-200 shadow-xl overflow-hidden flex flex-col h-full animate-in zoom-in-95 duration-500 hover:border-slate-300 transition-all">
      <div className={`p-8 ${colorClass} text-white relative`}>
        <div className="absolute top-0 right-0 p-8 opacity-10">
          <Swords className="w-16 h-16" />
        </div>
        <div className="flex justify-between items-center mb-2">
          <p className="text-[10px] font-black uppercase opacity-60 tracking-[0.3em]">Line-up Equipe</p>
          <p className="text-[10px] font-black uppercase opacity-60 tracking-[0.3em]">Média ELO</p>
        </div>
        <div className="flex justify-between items-end">
          <h3 className="font-black text-4xl tracking-tighter uppercase">{title}</h3>
          <p className="text-5xl font-black tracking-tighter">{team.totalElo}</p>
        </div>
      </div>

      <div className="p-8 space-y-8 flex-grow">
        <div className="space-y-4">
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2">Cérebro do Time</h4>
          {team.setter ? (
            <PlayerRow p={team.setter} isSetter />
          ) : (
            <div className="p-6 rounded-3xl border-2 border-dashed border-slate-100 bg-slate-50 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest italic">Aguardando Levantador</p>
            </div>
          )}
        </div>

        <div className="space-y-4">
          <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-2">Atacantes e Defesa</h4>
          <div className="grid grid-cols-1 gap-3">
            {team.players.map((p: Player) => (
              <PlayerRow key={p.id} p={p} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
